//! The Tauri commands and the types the frontend uses, from which
//! app/src/bindings.ts is generated by the `bindings_are_up_to_date` test
//! (see golden.rs).

use tauri_specta::{collect_commands, Builder, ErrorHandlingMode};

use crate::config::{self, CONFIG_LIMITS};
use crate::{face, face_session, fingerprint, models, system};

pub fn builder() -> Builder<tauri::Wry> {
    Builder::<tauri::Wry>::new()
        .commands(collect_commands![
            config::load_config,
            config::save_config,
            config::set_appearance,
            system::get_current_username,
            face_session::start_face_preview,
            face_session::stop_face_preview,
            face_session::capture_face_in_session,
            face::list_faces,
            system::list_video_devices,
            face::delete_face,
            fingerprint::enroll_fingerprint,
            fingerprint::remove_fingerprint,
            fingerprint::list_enrolled_fingerprints,
            models::list_models,
            models::add_model_from_url,
            models::add_model_from_file,
            models::delete_model,
            models::rename_model,
            models::ensure_default_models,
        ])
        .typ::<models::DownloadProgress>()
        .constant("CONFIG_LIMITS", CONFIG_LIMITS)
        // Commands reject with the error string, as plain `invoke` does.
        .error_handling(ErrorHandlingMode::Throw)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::golden;
    use specta_typescript::Typescript;

    #[test]
    fn bindings_are_up_to_date() {
        let dir = tempfile::tempdir().unwrap();
        let out = dir.path().join("bindings.ts");
        builder()
            .export(
                Typescript::default()
                    .header("// Generated by app/src-tauri/src/bindings.rs. Do not edit.\n"),
                &out,
            )
            .unwrap();
        golden::check(
            "app/src/bindings.ts",
            &std::fs::read_to_string(out).unwrap(),
        );
    }
}
